-- a break is the gap between two entries: retire break rows outside signed-off months (db/legacy-breaks.ts)
INSERT INTO revisions (entity, entity_id, subject_user_id, actor_id, action, before, after, reason, source, at) SELECT 'time_entry', e.id, e.user_id, NULL, 'delete', json_object('kind', e.kind, 'start_at', substr(e.start_at, 1, 23) || 'Z', 'end_at', CASE WHEN e.end_at IS NULL THEN NULL ELSE substr(e.end_at, 1, 23) || 'Z' END, 'scheduled_end_at', NULL, 'tz', e.tz, 'note', e.note, 'source', e.source, 'is_deleted', json('false')), json_object('kind', e.kind, 'start_at', substr(e.start_at, 1, 23) || 'Z', 'end_at', substr(COALESCE(e.end_at, strftime('%Y-%m-%dT%H:%M:%f000Z', 'now')), 1, 23) || 'Z', 'scheduled_end_at', NULL, 'tz', e.tz, 'note', e.note, 'source', e.source, 'is_deleted', json('true')), 'A break is the gap between two entries now', 'migration', strftime('%Y-%m-%dT%H:%M:%f000Z', 'now') FROM time_entries e WHERE e.kind = 'break' AND e.is_deleted = 0 AND NOT EXISTS (SELECT 1 FROM month_signoffs s WHERE s.user_id = e.user_id AND s.reopened_at IS NULL AND e.start_at < s.period_end_utc AND COALESCE(e.end_at, '9999-12-31T00:00:00.000000Z') > s.period_start_utc);
