UPDATE time_entries AS e SET is_deleted = 1, end_at = COALESCE(e.end_at, strftime('%Y-%m-%dT%H:%M:%f000Z', 'now')), updated_at = strftime('%Y-%m-%dT%H:%M:%f000Z', 'now') WHERE e.kind = 'break' AND e.is_deleted = 0 AND NOT EXISTS (SELECT 1 FROM month_signoffs s WHERE s.user_id = e.user_id AND s.reopened_at IS NULL AND e.start_at < s.period_end_utc AND COALESCE(e.end_at, '9999-12-31T00:00:00.000000Z') > s.period_start_utc);
